CREATE TABLE IF NOT EXISTS inventory_transactions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT, warehouse_id uuid NOT NULL REFERENCES warehouses(id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL, doc_type text NOT NULL, doc_id uuid NOT NULL, line_id uuid, direction text NOT NULL CHECK (direction IN ('in','out')), qty numeric(20,4) NOT NULL CHECK (qty > 0), base_qty numeric(20,4) NOT NULL CHECK (base_qty > 0), unit_cost numeric(20,4) NOT NULL CHECK (unit_cost >= 0), total_cost numeric(20,4) NOT NULL CHECK (total_cost >= 0), costing text NOT NULL, lot_id uuid, serial_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid);
CREATE INDEX IF NOT EXISTS inventory_transactions_scope_idx ON inventory_transactions(tenant_id, item_id, warehouse_id, occurred_at);
CREATE UNIQUE INDEX IF NOT EXISTS inventory_transactions_document_line_key ON inventory_transactions(tenant_id, doc_type, doc_id, line_id);
CREATE INDEX IF NOT EXISTS inventory_transactions_lot_idx ON inventory_transactions(tenant_id, lot_id);
CREATE INDEX IF NOT EXISTS inventory_transactions_serial_idx ON inventory_transactions(tenant_id, serial_id);
CREATE TABLE IF NOT EXISTS stock_balances (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT, warehouse_id uuid NOT NULL REFERENCES warehouses(id) ON DELETE RESTRICT, quantity numeric(20,4) NOT NULL DEFAULT 0, value numeric(20,4) NOT NULL DEFAULT 0, average_cost numeric(20,4) NOT NULL DEFAULT 0, version int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id, item_id, warehouse_id));
CREATE TABLE IF NOT EXISTS stock_adjustments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, warehouse_id uuid NOT NULL REFERENCES warehouses(id), branch_id uuid NOT NULL, number text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','cancelled')), reason text NOT NULL, approved_at timestamptz, approved_by uuid, journal_entry_id uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS stock_adjustments_tenant_number_key ON stock_adjustments(tenant_id, number);
CREATE TABLE IF NOT EXISTS stock_adjustment_lines (adjustment_id uuid NOT NULL REFERENCES stock_adjustments(id) ON DELETE CASCADE, line_no int NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), expected_qty numeric(20,4) NOT NULL, counted_qty numeric(20,4) NOT NULL, unit_cost numeric(20,4), lot_id uuid, note text, PRIMARY KEY(adjustment_id, line_no));
CREATE TABLE IF NOT EXISTS stock_transfers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, from_warehouse_id uuid NOT NULL REFERENCES warehouses(id), to_warehouse_id uuid NOT NULL REFERENCES warehouses(id), number text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','partially_received','received','cancelled')), sent_at timestamptz, received_at timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text, CHECK (from_warehouse_id <> to_warehouse_id));
CREATE UNIQUE INDEX IF NOT EXISTS stock_transfers_tenant_number_key ON stock_transfers(tenant_id, number);
CREATE TABLE IF NOT EXISTS stock_transfer_lines (transfer_id uuid NOT NULL REFERENCES stock_transfers(id) ON DELETE CASCADE, line_no int NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), qty numeric(20,4) NOT NULL CHECK (qty > 0), sent_qty numeric(20,4) NOT NULL DEFAULT 0, received_qty numeric(20,4) NOT NULL DEFAULT 0, unit_cost numeric(20,4) NOT NULL DEFAULT 0, lot_id uuid, serial_ids jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(transfer_id, line_no));
CREATE TABLE IF NOT EXISTS item_lots (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), lot_no text NOT NULL, expiry_date date, received_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS item_lots_tenant_item_lot_key ON item_lots(tenant_id, item_id, lot_no) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS item_serials (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), serial_no text NOT NULL, lot_id uuid, status text NOT NULL DEFAULT 'available', warehouse_id uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS item_serials_tenant_serial_key ON item_serials(tenant_id, serial_no) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS invoice_item_attributes (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, document_type text NOT NULL, document_id uuid NOT NULL, line_id uuid NOT NULL, attributes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS invoice_item_attributes_line_key ON invoice_item_attributes(tenant_id, document_type, document_id, line_id);
CREATE OR REPLACE FUNCTION prevent_inventory_transaction_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'inventory ledger is append-only' USING ERRCODE = '42501'; END; $$;
DROP TRIGGER IF EXISTS inventory_transactions_immutable ON inventory_transactions;
CREATE TRIGGER inventory_transactions_immutable BEFORE UPDATE OR DELETE ON inventory_transactions FOR EACH ROW EXECUTE FUNCTION prevent_inventory_transaction_mutation();
